parameters.jsCode:
const source =
  $json.body ?? $json;

const now =
  new Date();

const requestedCount =
  Number(
    source.requested_count ??
    source.target_count ??
    10
  );

const overfetchFactor =
  Number(
    source.overfetch_factor ??
    1
  );

if (
  !Number.isInteger(requestedCount) ||
  requestedCount < 1 ||
  requestedCount > 200
) {
  throw new Error(
    'requested_count must be an integer between 1 and 200'
  );
}

if (
  !Number.isFinite(overfetchFactor) ||
  overfetchFactor < 1
) {
  throw new Error(
    'overfetch_factor must be a number greater than or equal to 1'
  );
}

const discoveryTarget =
  Math.min(
    200,
    Math.ceil(
      requestedCount *
      overfetchFactor
    )
  );

const segment = String(
  source.segment ?? 'farrier'
).trim().toLowerCase();

if (
  ![
    'farrier',
    'horse_owner'
  ].includes(segment)
) {
  throw new Error(
    'segment must be farrier or horse_owner'
  );
}

function clean(value) {
  return value == null
    ? ''
    : String(value)
        .normalize('NFKC')
        .trim()
        .replace(/\s+/g, ' ');
}

function slug(value) {
  return clean(value)
    .toLowerCase()
    .normalize('NFKD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    )
    .replace(
      /[^a-z0-9]+/g,
      '-'
    )
    .replace(
      /^-|-$/g,
      ''
    );
}

const rawLocation =
  source.location;

if (
  !rawLocation ||
  typeof rawLocation !== 'object' ||
  Array.isArray(rawLocation)
) {
  throw new Error(
    'location must be an object'
  );
}

const city =
  clean(rawLocation.city);

const region =
  clean(
    rawLocation.region ||
    rawLocation.state ||
    rawLocation.state_region
  );

const regionCode =
  clean(
    rawLocation.region_code ||
    rawLocation.state_code
  ).toUpperCase();

const country =
  clean(rawLocation.country);

const countryCode =
  clean(
    rawLocation.country_code
  ).toUpperCase();

if (!city) {
  throw new Error(
    'location.city is required'
  );
}

if (!country) {
  throw new Error(
    'location.country is required'
  );
}

if (
  !/^[A-Z]{2}$/.test(
    countryCode
  )
) {
  throw new Error(
    'location.country_code must be a two-letter ISO country code'
  );
}

if (
  regionCode &&
  !/^[A-Z0-9-]{1,12}$/.test(
    regionCode
  )
) {
  throw new Error(
    'location.region_code/state_code contains invalid characters'
  );
}

/*
 * Current US directory adapters require a region
 * and stable region code.
 */
if (!region || !regionCode) {
  throw new Error(
    'US discovery requires location.region and location.region_code/state_code'
  );
}

const cityAliases = [
  ...new Set(
    (
      Array.isArray(
        rawLocation.city_aliases
      )
        ? rawLocation.city_aliases
        : []
    )
      .map(clean)
      .filter(Boolean)
  )
];

const citySlug =
  slug(city);

const regionSlug =
  slug(region);

const countrySlug =
  slug(country);

if (
  !citySlug ||
  !regionSlug ||
  !countrySlug
) {
  throw new Error(
    'The supplied location could not be converted to canonical slugs'
  );
}

const location = {
  city,
  city_slug:
    citySlug,

  city_aliases:
    cityAliases,

  region,
  region_code:
    regionCode,

  region_slug:
    regionSlug,

  /*
   * Compatibility aliases for existing
   * directory records.
   */
  state:
    region,

  state_code:
    regionCode,

  country,
  country_code:
    countryCode,

  country_slug:
    countrySlug,

  location_display:
    [
      city,
      region,
      country
    ]
      .filter(Boolean)
      .join(', ')
};

const locationKey = [
  countryCode,
  regionCode ||
    regionSlug ||
    '*',
  citySlug
].join('|');

const focus = [
  ...new Set(
    (
      Array.isArray(source.focus)
        ? source.focus
        : []
    )
      .map(
        value =>
          String(value)
            .trim()
            .toLowerCase()
      )
      .filter(Boolean)
  )
].sort();

const expectedPolicyVersion =
  source.source_policy_version || "2.0.0";


const sourcePolicyVersion =
  expectedPolicyVersion;

const sourceScopeKey = [
  sourcePolicyVersion,
  segment,
  locationKey,
  `focus:${focus.join(',')}`
].join('|');

const stamp =
  now
    .toISOString()
    .replace(
      /[-:.TZ]/g,
      ''
    )
    .slice(0, 14);

const suffix =
  Math.random()
    .toString(36)
    .slice(2, 8)
    .toUpperCase();

const runId = String(
  source.run_id ||
  `A1-${stamp}-${suffix}`
).trim();

if (
  !runId ||
  runId.length > 160 ||
  !/^[A-Za-z0-9._:-]+$/.test(
    runId
  )
) {
  throw new Error(
    'run_id contains invalid characters or is too long'
  );
}

return [{
  json: {
    run_id:
      runId,

    requested_count:
      requestedCount,

    discovery_target:
      discoveryTarget,

    overfetch_factor:
      overfetchFactor,

    segment,

    location,

    location_key:
      locationKey,

    source_scope_key:
      sourceScopeKey,

    focus,

    source_policy_version:
      sourcePolicyVersion,

    runtime_policy_version:
      '3.2.0',

    created_at:
      now.toISOString()
  }
}];

