source_scope_key: $json.source_scope_key, } }}

parameters.jsCode:
const run = $json;

const farrierSources = [
  { order: 1, id: 'pdf.mad_barn_directory', name: 'Mad Barn', type: 'directory', supportMultipleLocations:true },
  { order: 2, id: 'integration.apify_google_maps_scraper', name: 'Google Maps via Apify', type: 'google_maps', supportMultipleLocations:true },
  { order: 3, id: 'pdf.farrieriq', name: 'FarrierIQ', type: 'directory', supportMultipleLocations:true  },
  { order: 4, id: 'pdf.newhorse', name: 'NewHorse', type: 'directory', supportMultipleLocations:true  },
  { order: 5, id: 'pdf.horseprofinder', name: 'HorseProFinder', type: 'directory',supportMultipleLocations:true },
  { order: 6, id: 'pdf.best_of_lexington_farriers', name: 'Best of Lexington', type: 'directory', supportMultipleLocations:false }
];

// The six tested directory adapters are Farrier-focused. Replace this plan
// with approved Horse Owner adapters before enabling horse_owner runs.
if (run.segment === 'horse_owner') {
  const horseOwnerSources = [
    { order: 1, id: 'integration.apify_google_maps_scraper', name: 'Google Maps via Apify', type: 'google_maps', supportMultipleLocations:true },
  { order: 2, id: 'pdf.horseprofinder', name: 'HorseProFinder', type: 'directory', supportMultipleLocations:true }
                            ]
  return horseOwnerSources.slice(-2).map(source=>({
     json: {
    ...run,
    source_order: source.order,
    source_id: source.id,
    source_name: source.name,
    source_type: source.type,
  }
  }))
}

if(run.location.country_code.toLowerCase() !== "US" && run.location.state.toLowerCase() !== "kentucky"){

  return farrierSources.slice(0,5).map(source =>({json:{
    ...run,
    source_order: source.order,
    source_id: source.id,
    source_name: source.name,
    source_type: source.type,
  }}))
}

return farrierSources.map(source => ({
  json: {
    ...run,
    source_order: source.order,
    source_id: source.id,
    source_name: source.name,
    source_type: source.type,
  }
}));

const item =
  $json || {};

const discoveryTarget =
  Number(
    item.discovery_target || 0
  );

const uniqueLeadsFound =
  Number(
    item.unique_leads_found || 0
  );

const remainingTarget =
  Math.max(
    0,
    discoveryTarget -
    uniqueLeadsFound
  );

const sourceStatus =
  String(
    item.source_status ||
    'pending'
  ).toLowerCase();

const sourceFinished = [
  'completed',
  'exhausted'
].includes(sourceStatus);

const targetReached =
  remainingTarget <= 0;

const shouldRun =
  !targetReached &&
  !sourceFinished &&
  remainingTarget > 0;

return [{
  json: {
    ...item,

    remaining_target:
      remainingTarget,

    max_results:
      remainingTarget,

    maximum_results:
      remainingTarget,

    previous_position:
      item.cursor || {},

    target_reached:
      targetReached,

    source_finished:
      sourceFinished,

    should_run:
      shouldRun
  }
}];

const context =
  $('Decide Whether to Run Source')
    .item.json;

const response =
  $json.body ?? $json;

const rawRecords =
  Array.isArray(response.records)
    ? response.records
    : [];

function text(value) {
  return value == null
    ? ''
    : String(value).trim();
}

function domain(value) {
  const raw =
    text(value).toLowerCase();

  if (!raw) {
    return '';
  }

  try {

    return raw
      .toLowerCase()
      .replace(/^www\./, '')
      .replace(/\.$/, '');
  } catch {
    return '';
  }
}

function phone(value) {
  return text(value)
    .replace(/\D/g, '');
}

function slug(value) {
  return text(value)
    .toLowerCase()
    .normalize('NFKD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    )
    .replace(
      /[^a-z0-9]+/g,
      '-'
    )
    .replace(
      /^-|-$/g,
      ''
    );
}

function unique(values) {
  return [
    ...new Set(
      values.filter(Boolean)
    )
  ];
}

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function isEmptyObject(value) {
  return (
    isPlainObject(value) &&
    Object.keys(value).length === 0
  );
}

let adapterStatus = String(
  response.status ||
  (
    response.source_exhausted
      ? 'completed'
      : 'partial'
  )
).toLowerCase();

let adapterError =
  response.error || null;

const sourceWarnings =
  Array.isArray(response.warnings)
    ? response.warnings
    : [];

const sourceExhausted =
  Boolean(
    response.source_exhausted
  );

const responseLocationKey =
  text(response.location_key);

const responseScopeKey =
  text(
    response.source_scope_key
  );

if (
  responseLocationKey &&
  responseLocationKey !==
    context.location_key
) {
  adapterStatus =
    'failed';

  adapterError = {
    code:
      'SOURCE_LOCATION_MISMATCH',

    message:
      `${context.source_id} returned ` +
      `location_key=${responseLocationKey}; ` +
      `expected ${context.location_key}.`,

    retryable:
      false,

    stage:
      'adapter_contract'
  };
}

if (
  !adapterError &&
  responseScopeKey &&
  responseScopeKey !==
    context.source_scope_key
) {
  adapterStatus =
    'failed';

  adapterError = {
    code:
      'SOURCE_SCOPE_MISMATCH',

    message:
      `${context.source_id} returned a different ` +
      `source_scope_key.`,

    retryable:
      false,

    stage:
      'adapter_contract'
  };
}

const rawNextCursor =
  response.next_position ??
  response.next_cursor ??
  {};

let nextCursor =
  isPlainObject(rawNextCursor)
    ? rawNextCursor
    : {};

if (
  !adapterError &&
  !isPlainObject(rawNextCursor)
) {
  adapterStatus =
    'failed';

  adapterError = {
    code:
      'SOURCE_CURSOR_INVALID',

    message:
      `${context.source_id} returned a cursor that is not an object.`,

    retryable:
      false,

    stage:
      'adapter_contract'
  };
}

const successfulStatus =
  [
    'completed',
    'partial'
  ].includes(adapterStatus);

if (
  !adapterError &&
  successfulStatus &&
  isEmptyObject(nextCursor)
) {
  adapterStatus =
    'failed';

  adapterError = {
    code:
      'SOURCE_CURSOR_MISSING',

    message:
      `${context.source_id} returned a successful result without a terminal or continuation cursor.`,

    retryable:
      false,

    stage:
      'adapter_contract'
  };
}

if (
  !adapterError &&
  successfulStatus &&
  !isEmptyObject(nextCursor)
) {
  const cursorSourceId =
    text(nextCursor.source_id);

  const cursorSegment =
    text(nextCursor.segment);

  const cursorLocationKey =
    text(nextCursor.location_key);

  const cursorScopeKey =
    text(
      nextCursor.scope_key ||
      nextCursor.source_scope_key
    );

  if (
    cursorSourceId &&
    cursorSourceId !==
      context.source_id
  ) {
    adapterStatus =
      'failed';

    adapterError = {
      code:
        'SOURCE_CURSOR_SOURCE_MISMATCH',

      message:
        'Returned cursor belongs to another source.',

      retryable:
        false,

      stage:
        'adapter_contract'
    };
  } else if (
    cursorSegment &&
    cursorSegment !==
      context.segment
  ) {
    adapterStatus =
      'failed';

    adapterError = {
      code:
        'SOURCE_CURSOR_SEGMENT_MISMATCH',

      message:
        'Returned cursor belongs to another segment.',

      retryable:
        false,

      stage:
        'adapter_contract'
    };
  } else if (
    cursorLocationKey &&
    cursorLocationKey !==
      context.location_key
  ) {
    adapterStatus =
      'failed';

    adapterError = {
      code:
        'SOURCE_CURSOR_LOCATION_MISMATCH',

      message:
        'Returned cursor belongs to another location.',

      retryable:
        false,

      stage:
        'adapter_contract'
    };
  } 

  if (!adapterError) {
    nextCursor = {
      ...nextCursor,

      source_id:
        context.source_id,

      segment:
        context.segment,

      location_key:
        context.location_key,

      scope_key:
        context.source_scope_key,

      source_exhausted:
        sourceExhausted
    };
  }
}

let records =
  rawRecords
    .map(record => {
      const name =
        text(
          record.business_name ||
          record.name
        );

      const websiteDomain =
        domain(record.website);

      const normalizedPhone =
        phone(record.phone);

      const placeId =
        text(
          record.google_place_id ||
          record.place_id
        );

      const addressKey =
        slug(
          [
            record.address,
            record.city,
            record.region,
            record.state,
            record.postal_code,
            record.country,
            record.country_code
          ]
            .filter(Boolean)
            .join(' ')
        );

      const sourceRecordId =
        text(
          record.source_record_id ||
          record.id
        );

      if (!sourceRecordId) {
        return null;
      }

      const identityKeys =
        unique([
          placeId
            ? `place:${placeId}`
            : '',

          websiteDomain
            ? `domain:${websiteDomain}`
            : '',

          normalizedPhone
            ? `phone:${normalizedPhone}`
            : '',

          name && addressKey
            ? (
                `name-address:` +
                `${slug(name)}:` +
                `${addressKey}`
              )
            : '',

          `source:${context.source_id}:` +
          `${sourceRecordId}`
        ]);

      const fingerprint =
        identityKeys[0];

      return {
        lead_fingerprint:
          fingerprint,

        identity_keys:
          identityKeys,

        source_record_id:
          sourceRecordId,

        source_url:
          text(
            record.source_url ||
            record.listing_url
          ),

        name:
          text(record.name),

        business_name:
          text(
            record.business_name ||
            record.name
          ),

        person_name:
          text(record.person_name),

        entity_type:
          text(record.entity_type),

        segment_hint:
          text(
            record.segment_hint ||
            context.segment
          ),

        website:
          text(record.website),

        phone:
          text(record.phone),

        email:
          text(record.email),

        address:
          text(record.address),

        city:
          text(record.city),

        region:
          text(
            record.region ||
            record.state
          ),

        region_code:
          text(
            record.region_code ||
            record.state_code
          ),

        state:
          text(
            record.state ||
            record.region
          ),

        state_code:
          text(
            record.state_code ||
            record.region_code
          ),

        postal_code:
          text(record.postal_code),

        country:
          text(
            record.country ||
            context.location?.country
          ),

        country_code:
          text(
            record.country_code ||
            context.location?.country_code
          ),

        google_place_id:
          placeId,

        source_notes:
          Array.isArray(
            record.source_notes
          )
            ? record.source_notes
            : [],

        raw:
          record
      };
    })
    .filter(Boolean);

if (
  rawRecords.length >
  Number(context.max_results || 0)
) {
  adapterStatus =
    'failed';

  adapterError = {
    code:
      'SOURCE_RESULT_LIMIT_EXCEEDED',

    message:
      `${context.source_id} returned ` +
      `${rawRecords.length} records for ` +
      `max_results=${context.max_results}.`,

    retryable:
      false,

    stage:
      'adapter_contract'
  };

  records = [];
}

if (adapterError) {
  /*
   * The persistence SQL also protects the old
   * cursor, but keeping it here makes the item
   * contract explicit.
   */
  nextCursor =
    context.cursor || {};
} else if (
  [
    'completed',
    'partial'
  ].includes(adapterStatus)
) {
  adapterStatus =
    sourceExhausted
      ? 'exhausted'
      : 'partial';
}

return [{
  json: {
    ...context,

    adapter_status:
      adapterStatus,

    source_exhausted:
      sourceExhausted,

    next_cursor:
      nextCursor,

    adapter_error:
      adapterError,

    adapter_warnings:
      sourceWarnings,

    records
  }
}];

const items = $input.all();
if (!items.length) throw new Error('No source items reached the loop completion output');
return [{ json: { run_id: items[0].json.run_id } }];

const payload = $json.payload ?? {};

function text(value) {
  return value == null
    ? ''
    : String(value)
        .normalize('NFKC')
        .trim()
        .replace(/\s+/g, ' ');
}

function splitHttpUrl(
  value,
  defaultScheme = 'https'
) {
  let candidate =
    text(value)
      .replace(/^[<("'`]+/, '')
      .replace(/[>)"'`,.;]+$/, '');

  if (!candidate) {
    return null;
  }

  if (!/^https?:\/\//i.test(candidate)) {
    candidate =
      `${defaultScheme}://${candidate}`;
  }

  const match =
    candidate.match(
      /^(https?):\/\/([^/?#\s]+)([/?#][^\s]*)?$/i
    );

  if (
    !match ||
    match[2].includes('@')
  ) {
    return null;
  }

  const authority =
    match[2];

  const authorityMatch =
    authority.match(
      /^([^:]+)(?::([0-9]{1,5}))?$/
    );

  if (!authorityMatch) {
    return null;
  }

  const hostname =
    authorityMatch[1]
      .toLowerCase()
      .replace(/\.$/, '');

  const port =
    authorityMatch[2] || '';

  /*
   * Keep the current no-nonstandard-port control.
   */
  if (
    port &&
    !['80', '443'].includes(port)
  ) {
    return null;
  }

  if (
    hostname.length > 253 ||
    !hostname.includes('.') ||
    hostname.includes('..')
  ) {
    return null;
  }

  const labels =
    hostname.split('.');

  const validLabels =
    labels.every(label =>
      /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i
        .test(label)
    );

  if (!validLabels) {
    return null;
  }

  const topLevelDomain =
    labels[labels.length - 1];

  if (
    !/^(?:[a-z]{2,63}|xn--[a-z0-9-]{2,59})$/i
      .test(topLevelDomain)
  ) {
    return null;
  }

  let suffix =
    match[3] || '/';

  /*
   * Remove fragments without using URL().
   */
  const hashIndex =
    suffix.indexOf('#');

  if (hashIndex >= 0) {
    suffix =
      suffix.slice(0, hashIndex);
  }

  if (!suffix) {
    suffix = '/';
  }

  if (suffix.startsWith('?')) {
    suffix =
      `/${suffix}`;
  }

  return {
    scheme:
      match[1].toLowerCase(),

    hostname,

    port,

    suffix
  };
}


function canonicalDomain(value) {
  const parsed =
    splitHttpUrl(
      value,
      'https'
    );

  if (!parsed) {
    return '';
  }

  return parsed.hostname
    .replace(/^www\./, '');
}

function normalizedName(value) {
  return text(value)
    .toLocaleLowerCase('en-US');
}

/*
 * This uses payload.name exactly as requested.
 *
 * If your adapters reliably put the person's name in
 * payload.person_name, use:
 *
 * const contactName =
 *   text(payload.person_name || payload.name);
 */
const contactName =
  text(payload.name);

return [{
  json: {
    run_id: $json.run_id,

    lead_fingerprint: $json.lead_fingerprint,

    payload,

    hubspot_domain:
      canonicalDomain(payload.website),

    hubspot_contact_name:
      contactName,

    hubspot_contact_name_key:
      normalizedName(contactName),

    business_name:
      text(
        payload.business_name ||
        payload.name
      )
  }
}];

const context = $('Prepare HubSpot Lookup').item.json;
const rows = $input.all().map(item => item.json ?? {});

const errorRow = rows.find(row =>
  row.error ||
  Number(row.statusCode || 0) >= 400 ||
  row.message?.toLowerCase?.().includes('error')
);
const matches = rows.filter(row =>
  !row.error &&
  (row.id || row.companyId) &&
  Object.keys(row).length > 0
);

return [{
  json: {
    ...context,
    hubspot_search_error: errorRow
      ? String(errorRow.error?.message || errorRow.error || errorRow.message || 'HubSpot search failed')
      : null,
    hubspot_matches: matches
  }
}];

const matches = Array.isArray($json.hubspot_matches)
  ? $json.hubspot_matches
  : [];

const error = $json.hubspot_search_error || null;

function propertyValue(row, name) {
  const value = row?.properties?.[name];

  if (value && typeof value === 'object' && 'value' in value) {
    return value.value;
  }

  return value ?? null;
}

if (error) {
  return [{
    json: {
      ...$json,
      lead_status: 'hubspot_check_failed',
      search_method: 'company_domain',
      domain_available: true,
      hubspot_match: {
        status: 'check_failed',
        checked_key: `domain:${$json.hubspot_domain}`,
        error
      }
    }
  }];
}

if (matches.length > 0) {
  const first = matches[0];

  return [{
    json: {
      ...$json,
      lead_status: 'hubspot_duplicate',
      search_method: 'company_domain',
      domain_available: true,
      hubspot_match: {
        status: 'clear_duplicate',
        object_type: 'company',
        object_id: String(first.id || first.companyId),
        match_key: `domain:${$json.hubspot_domain}`,
        matched_property: 'domain',
        confidence: 1,
        company_name:
          propertyValue(first, 'name') ||
          first.name ||
          null,
        match_count: matches.length,
        multiple_hubspot_records: matches.length > 1
      }
    }
  }];
}

return [{
  json: {
    ...$json,
    lead_status: 'eligible',
    search_method: 'company_domain',
    domain_available: true,
    hubspot_match: {
      status: 'no_match',
      checked_key: `domain:${$json.hubspot_domain}`,
      matched_property: null,
      confidence: 0
    }
  }
}];

const runId =
  $('Collapse Completed Source Loop').first().json.run_id;

return [{
  json: {
    run_id: runId
  }
}];

const item =
  $json || {};

if (
  item.resume_scope_valid !== true
) {
  throw new Error(
    `run_id ${item.run_id || 'unknown'} already ` +
    `exists with a different immutable request scope: ` +
    `${JSON.stringify(
      item.resume_scope_comparison || {}
    )}`
  );
}

return [{
  json: item
}];

const context =
  $('Prepare HubSpot Lookup')
    .item.json;

const inputRows =
  $input
    .all()
    .map(item => item.json ?? {});

const errorRow =
  inputRows.find(row =>
    row.error ||
    Number(row.statusCode || 0) >= 400 ||
    (
      !row.id &&
      typeof row.message === 'string' &&
      /error|unauthori[sz]ed|rate limit/i
        .test(row.message)
    )
  );

/*
 * Native HubSpot Search normally emits one item per
 * contact. The results handling also tolerates a raw
 * HubSpot Search API envelope.
 */
const rows =
  inputRows.flatMap(row =>
    Array.isArray(row.results)
      ? row.results
      : [row]
  );

function propertyValue(row, name) {
  const value =
    row?.properties?.[name];

  if (
    value &&
    typeof value === 'object' &&
    'value' in value
  ) {
    return value.value;
  }

  return value ??
    row?.[name] ??
    null;
}

function normalizedName(value) {
  return value == null
    ? ''
    : String(value)
        .normalize('NFKC')
        .trim()
        .replace(/\s+/g, ' ')
        .toLocaleLowerCase('en-US');
}

const queryRows =
  rows.filter(row =>
    !row.error &&
    (row.id || row.contactId) &&
    Object.keys(row).length > 0
  );

const exactMatches =
  queryRows.filter(row => {
    const fullName = [
      propertyValue(row, 'firstname'),
      propertyValue(row, 'lastname')
    ]
      .filter(Boolean)
      .join(' ');

    return (
      normalizedName(fullName) ===
      context.hubspot_contact_name_key
    );
  });

return [{
  json: {
    ...context,

    hubspot_search_error:
      errorRow
        ? String(
            errorRow.error?.message ||
            errorRow.error ||
            errorRow.message ||
            'HubSpot Contact search failed'
          )
        : null,

    hubspot_query_result_count:
      queryRows.length,

    hubspot_matches:
      exactMatches
  }
}];

const matches =
  Array.isArray($json.hubspot_matches)
    ? $json.hubspot_matches
    : [];

const error =
  $json.hubspot_search_error ||
  null;

function propertyValue(row, name) {
  const value =
    row?.properties?.[name];

  if (
    value &&
    typeof value === 'object' &&
    'value' in value
  ) {
    return value.value;
  }

  return value ??
    row?.[name] ??
    null;
}

const checkedKey =
  `contact_name:${$json.hubspot_contact_name_key}`;

if (error) {
  return [{
    json: {
      ...$json,

      lead_status:
        'hubspot_check_failed',

      hubspot_match: {
        status:
          'check_failed',

        object_type:
          'contact',

        search_method:
          'contact_name_query_exact_postfilter',

        domain_available:
          false,

        checked_key:
          checkedKey,

        checked_name:
          $json.hubspot_contact_name,

        error
      }
    }
  }];
}

if (matches.length > 0) {
  const matchedContacts =
    matches.map(row => ({
      object_id:
        String(
          row.id ||
          row.contactId
        ),

      full_name: [
        propertyValue(row, 'firstname'),
        propertyValue(row, 'lastname')
      ]
        .filter(Boolean)
        .join(' '),

      company:
        propertyValue(row, 'company') ||
        null,

      city:
        propertyValue(row, 'city') ||
        null,

      region:
        propertyValue(row, 'state') ||
        null,

      country:
        propertyValue(row, 'country') ||
        null
    }));

  return [{
    json: {
      ...$json,

      /*
       * Name alone is not strong enough for an
       * automatic duplicate decision.
       */
      lead_status:
        'possible_duplicate',

      hubspot_match: {
        status:
          'possible_match',

        object_type:
          'contact',

        search_method:
          'contact_name_query_exact_postfilter',

        domain_available:
          false,

        checked_key:
          checkedKey,

        checked_name:
          $json.hubspot_contact_name,

        matched_property:
          'firstname+lastname',

        match_strength:
          'exact_normalized_full_name_only',

        object_id:
          matchedContacts[0].object_id,

        object_ids:
          matchedContacts.map(
            contact => contact.object_id
          ),

        matched_contacts:
          matchedContacts,

        match_count:
          matchedContacts.length,

        query_result_count:
          Number(
            $json.hubspot_query_result_count ||
            0
          ),

        multiple_hubspot_records:
          matchedContacts.length > 1,

        requires_human_review:
          true
      }
    }
  }];
}

return [{
  json: {
    ...$json,

    lead_status:
      'eligible',

    hubspot_match: {
      status:
        'no_match',

      object_type:
        'contact',

      search_method:
        'contact_name_query_exact_postfilter',

      domain_available:
        false,

      checked_key:
        checkedKey,

      checked_name:
        $json.hubspot_contact_name,

      matched_property:
        null,

      query_result_count:
        Number(
          $json.hubspot_query_result_count ||
          0
        )
    }
  }
}];
